// Poisson rate encoder: one boolean per time step
function poissonTrain(x, maxRateHz, T_ms, dt_ms, rand = Math.random) {
  const p = x * maxRateHz * dt_ms / 1000; // spike probability per step
  const spikes = [];
  for (let t = 0; t < T_ms; t += dt_ms) if (rand() < p) spikes.push(t);
  return spikes;
}
